    test('parses all fields from JSON', () {
      final params = CliAgentParams.fromJson({
        'cliCommands': ['echo hello', 'echo world'],
        'cliPrompt': 'Do the thing',
        'setup': 'make setup',
        'cache': 'make cache',
        'reset': 'make reset',
        'preCliJSAction': 'pre.js',
        'cleanupInputFolder': false,
        'requireCliOutputFile': true,
