void resolveCliPromptsTests() {
  group('CliCommandBuilder.resolveCliPrompts', () {
    test('merges base with matching tracker prompts', () {
      expect(
        CliCommandBuilder.resolveCliPrompts(
          ['base1'],
          {
            'jira': ['j1', 'j2']
          },
          'jira',
        ),
        ['base1', 'j1', 'j2'],
