    });

    test('falls back to cli-agent', () {
      expect(CliAgentParams.fromJson({}).contextId, 'cli-agent');
      expect(CliAgentParams.fromJson({'metadata': {}}).contextId, 'cli-agent');
    });
  });
}

void paramsCliPromptsTests() {
