import 'package:dmtools/dmtools.dart';
import 'package:test/test.dart';

void main() {
  boundedLogBasicTests();
  boundedLogBoundaryTests();
  failureSummaryTests();
  successFallbackTests();
  monitoredPathTests();
  requireOutputFileTests();
  downstreamMarkerContractTests();
