library;

import 'dart:io';

import 'package:dmtools/dmtools.dart';
import 'package:test/test.dart';

void main() {
  group('CliAgent strict-mode postJSAction guard (gh-316)', () {
    test('skips postJSAction when strict-mode CLI produces no output file',
