        );
        expect(
          result['response'],
          startsWith(
            'CLI command executed but did not produce output file',
          ),
          reason: 'the error summary must still report the failure',
        );
      } finally {
        await h.dispose();
      }
    });

    test('runs postJSAction when the strict-mode CLI writes the output file',
        () async {
